package com.asmj.marketplace.analytics.service;import com.asmj.marketplace.analytics.model.AnalyticsEvent;import com.asmj.marketplace.analytics.repository.AnalyticsRepository;import com.asmj.marketplace.booking.repository.BookingRepository;import com.asmj.marketplace.application.repository.JobApplicationRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.*;@Service@RequiredArgsConstructor public class AnalyticsService{private final AnalyticsRepository repo;private final BookingRepository bookings;private final JobApplicationRepository applications;public AnalyticsEvent record(String event,String postId,String userId,String vendorId){return repo.save(AnalyticsEvent.builder().event(event).postId(postId).userId(userId).vendorId(vendorId).createdAt(Instant.now()).build());}public Map<String,Object> summary(){Map<String,Object> m=new LinkedHashMap<>();m.put("totalEvents",repo.count());m.put("views",repo.countByEvent("VIEW"));m.put("enquiries",repo.countByEvent("ENQUIRY"));m.put("favorites",repo.countByEvent("FAVORITE"));m.put("chatMessages",repo.countByEvent("CHAT_MESSAGE"));m.put("transactions",bookings.count());m.put("jobApplications",applications.count());m.put("completedTransactions",bookings.findAll().stream().filter(b->Set.of("COMPLETED","DELIVERED","RETURNED","ATTENDED").contains(b.getStatus())).count());return m;}public long vendorEvents(String vendorId){return repo.countByVendorId(vendorId);}public Map<String,Object> vendorSummary(String vendorId){Map<String,Object> m=new LinkedHashMap<>();m.put("events",repo.countByVendorId(vendorId));m.put("views",repo.countByVendorIdAndEvent(vendorId,"VIEW"));m.put("enquiries",repo.countByVendorIdAndEvent(vendorId,"ENQUIRY"));m.put("favorites",repo.countByVendorIdAndEvent(vendorId,"FAVORITE"));m.put("chatMessages",repo.countByVendorIdAndEvent(vendorId,"CHAT_MESSAGE"));m.put("transactions",bookings.findByVendorIdOrderByCreatedAtDesc(vendorId).size());m.put("jobApplications",applications.findByVendorIdOrderByCreatedAtDesc(vendorId).size());return m;}}
